import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
}

export interface IssueAttachment extends Timestamps, TenantScoped {
  readonly id: AttachmentId;
  readonly issueId: IssueId;
  readonly filename: string;
  readonly contentType: string;
  readonly sizeBytes: number;
  readonly uploadedBy: UserId;
}

/** Filter accepted by the issue repository, service layer and list UI alike. */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | null;
  readonly authorId?: UserId;
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  readonly dueBefore?: IsoTimestamp;
  readonly includeArchived?: boolean;
}

export interface IssueWithRelations {
  readonly issue: Issue;
  readonly labels: readonly IssueLabel[];
  readonly commentCount: number;
  readonly attachmentCount: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {
  readonly status: IssueStatus;
  readonly issues: readonly Issue[];
  readonly total: number;
}
/**
 * Primitive identifier and envelope types shared by every Taskflow domain type.
 *
 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
 * strings at runtime; the brand exists only at the type level.
 */

declare const brand: unique symbol;

/** Attaches a compile-time-only tag to a primitive type. */
export type Branded<T, B extends string> = T & { readonly [brand]: B };

export type UserId = Branded<string, "UserId">;
export type OrgId = Branded<string, "OrgId">;
export type ProjectId = Branded<string, "ProjectId">;
export type IssueId = Branded<string, "IssueId">;
export type CommentId = Branded<string, "CommentId">;
export type MemberId = Branded<string, "MemberId">;
export type NotificationId = Branded<string, "NotificationId">;
export type ActivityId = Branded<string, "ActivityId">;
export type InvitationId = Branded<string, "InvitationId">;
export type LabelId = Branded<string, "LabelId">;
export type AttachmentId = Branded<string, "AttachmentId">;
export type SubscriptionId = Branded<string, "SubscriptionId">;
export type SessionId = Branded<string, "SessionId">;
export type WebhookId = Branded<string, "WebhookId">;

/** Union of every branded id used in the app, for generic id helpers. */
export type AnyId =
  | UserId
  | OrgId
  | ProjectId
  | IssueId
  | CommentId
  | MemberId
  | NotificationId
  | ActivityId
  | InvitationId
  | LabelId
  | AttachmentId
  | SubscriptionId
  | SessionId
  | WebhookId;

/** ISO-8601 timestamp string as stored in SQLite text columns. */
export type IsoTimestamp = Branded<string, "IsoTimestamp">;

/** Rows carrying the standard created/updated bookkeeping columns. */
export interface Timestamps {
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
 * writing the predicate by hand.
 */
export interface SoftDeletable {
  readonly archivedAt: IsoTimestamp | null;
}

/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
export interface TenantScoped {
  readonly orgId: OrgId;
}

export type SortDirection = "asc" | "desc";

export interface SortSpec<TField extends string = string> {
  readonly field: TField;
  readonly direction: SortDirection;
}

/** Cursor pagination request shared by every repository `list*` method. */
export interface PageRequest {
  readonly limit: number;
  readonly cursor?: string | null;
}

/** Cursor pagination response shared by every repository `list*` method. */
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly total: number;
}

/** Options accepted by every soft-delete-aware repository read. */
export interface ArchiveScope {
  readonly includeArchived?: boolean;
}

export function makePage<T>(
  items: readonly T[],
  nextCursor: string | null,
  total: number,
): Page<T> {
  return { items, nextCursor, total };
}

export function toIsoTimestamp(value: Date | string): IsoTimestamp {
  const date = typeof value === "string" ? new Date(value) : value;
  return date.toISOString() as IsoTimestamp;
}
import { z } from "zod";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
  WebhookId,
} from "@/types/common";

/**
 * Shared Zod primitives.
 *
 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
 * on the server. Keep them free of server-only imports.
 */

const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/** Builds a branded-id schema whose output type is the branded alias. */
function brandedId<T extends string>(label: string) {
  return z
    .string()
    .regex(ULID, `${label} must be a ULID`)
    .transform((value) => value as T);
}

export const userIdSchema = brandedId<UserId>("userId");
export const orgIdSchema = brandedId<OrgId>("orgId");
export const projectIdSchema = brandedId<ProjectId>("projectId");
export const issueIdSchema = brandedId<IssueId>("issueId");
export const commentIdSchema = brandedId<CommentId>("commentId");
export const memberIdSchema = brandedId<MemberId>("memberId");
export const notificationIdSchema = brandedId<NotificationId>("notificationId");
export const activityIdSchema = brandedId<ActivityId>("activityId");
export const invitationIdSchema = brandedId<InvitationId>("invitationId");
export const labelIdSchema = brandedId<LabelId>("labelId");
export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
export const webhookIdSchema = brandedId<WebhookId>("webhookId");

export const isoTimestampSchema = z
  .iso
  .datetime()
  .transform((value) => value as IsoTimestamp);

export const emailSchema = z.email().max(254).toLowerCase();

export const sortDirectionSchema = z.enum(["asc", "desc"]);

export const pageRequestSchema = z.object({
  limit: z.number().int().min(1).max(100).default(25),
  cursor: z.string().nullable().optional(),
});

export const archiveScopeSchema = z.object({
  includeArchived: z.boolean().optional(),
});

export const hexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");

export type PageRequestInput = z.infer<typeof pageRequestSchema>;
export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;

"use client";

/**
 * Filter chips writing back into the URL search params.
 */
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, type SelectOption } from "@/components/ui/select";
import { humanizeStatus } from "@/lib/format";
import { activeFilterCount, UNASSIGNED_TOKEN } from "@/hooks/issue-filter-params";
import { ISSUE_STATUSES, type IssueFilter, type IssueStatus } from "@/types/issue";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { Project } from "@/types/project";
import type { ProjectId } from "@/types/common";
import type { ReactElement } from "react";

export type IssueFilterBarProps = {
  filter: IssueFilter;
  projects: readonly Project[];
  members: readonly MemberWithUser[];
  onChange: (filter: IssueFilter) => void;
};

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

export function IssueFilterBar(
  props: IssueFilterBarProps,
): ReactElement | null {
  const { filter, projects, members, onChange } = props;

  const projectOptions: readonly SelectOption[] = [
    { value: "", label: "All projects" },
    ...projects.map((project) => ({
      value: project.id,
      label: project.name,
    })),
  ];

  const assigneeOptions: readonly SelectOption[] = [
    { value: "", label: "Anyone" },
    { value: UNASSIGNED_TOKEN, label: "Unassigned" },
    ...members.map((member) => ({
      value: member.userId,
      label: member.user.name,
    })),
  ];

  return (
    <div className="flex flex-wrap items-center gap-2">
      <Input
        name="q"
        type="search"
        value={filter.query ?? ""}
        placeholder="Search issues"
        onChange={(value) =>
          onChange(value.length === 0 ? stripQuery(filter) : { ...filter, query: value })
        }
      />

      <Select
        name="project"
        value={filter.projectId ?? ""}
        options={projectOptions}
        onChange={(value) =>
          onChange(
            value.length === 0
              ? stripProject(filter)
              : { ...filter, projectId: value as ProjectId },
          )
        }
      />

      <Select
        name="assignee"
        value={
          filter.assigneeId === undefined
            ? ""
            : (filter.assigneeId ?? UNASSIGNED_TOKEN)
        }
        options={assigneeOptions}
        onChange={(value) => onChange(withAssignee(filter, value))}
      />

      <div className="flex flex-wrap gap-1">
        {ISSUE_STATUSES.map((status) => {
          const active = (filter.status ?? []).includes(status);
          return (
            <Button
              key={status}
              variant={active ? "primary" : "ghost"}
              size="sm"
              onClick={() => onChange(toggleStatus(filter, status))}
            >
              {humanizeStatus(status)}
            </Button>
          );
        })}
      </div>

      {activeFilterCount(filter) > 0 ? (
        <Button variant="ghost" size="sm" onClick={() => onChange({})}>
          Clear ({activeFilterCount(filter)})
        </Button>
      ) : null}
    </div>
  );
}

function stripQuery(filter: IssueFilter): IssueFilter {
  const { query: _query, ...rest } = filter;
  return rest;
}

function stripProject(filter: IssueFilter): IssueFilter {
  const { projectId: _projectId, ...rest } = filter;
  return rest;
}

function withAssignee(filter: IssueFilter, raw: string): IssueFilter {
  if (raw.length === 0) {
    const { assigneeId: _assigneeId, ...rest } = filter;
    return rest;
  }
  return {
    ...filter,
    assigneeId: raw === UNASSIGNED_TOKEN ? null : (raw as UserId),
  };
}
/**
